const planningStyles = ".goalflowz-progress-bar-container {\n    width: 100px;\n    height: 8px;\n    background: var(--background-modifier-border);\n    border-radius: 4px;\n    position: relative;\n    overflow: hidden;\n    margin-right: 1rem;\n}\n\n.goalflowz-progress-bar {\n    height: 100%;\n    background: var(--text-accent);\n    border-radius: 4px;\n    transition: width 0.3s ease;\n}\n\n.goalflowz-progress-text {\n    position: absolute;\n    right: -25px;\n    top: 50%;\n    transform: translateY(-50%);\n    color: var(--text-muted);\n    font-size: 0.7em;\n    white-space: nowrap;\n}\n\n/* Styles pour les tâches */\n.goalflowz-tasks-list {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    width: 100%;\n    padding: 8px 0;\n}\n\n.goalflowz-task-item {\n    width: 100%;\n    padding: 0 8px;\n}\n\n.goalflowz-task-item-content {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    width: 100%;\n    padding: 8px;\n    border-radius: 4px;\n    transition: all 0.2s ease;\n    cursor: pointer;\n}\n\n.goalflowz-task-item-content:hover {\n    background-color: var(--background-modifier-hover);\n    transform: translateX(4px);\n}\n\n.goalflowz-task-checkbox {\n    width: 18px;\n    height: 18px;\n    border: 2px solid var(--text-muted);\n    border-radius: 4px;\n    transition: all 0.2s ease;\n    flex-shrink: 0;\n}\n\n.goalflowz-task-checkbox.checked {\n    background-color: var(--text-accent);\n    border-color: var(--text-accent);\n}\n\n.goalflowz-task-item-content:hover .goalflowz-task-checkbox:not(.checked) {\n    border-color: var(--text-accent);\n    transform: scale(1.1);\n}\n\n.goalflowz-task-label {\n    flex: 1;\n    transition: all 0.2s ease;\n    padding: 4px 0;\n}\n\n.goalflowz-task-label.done {\n    text-decoration: line-through;\n    color: var(--text-muted);\n}\n\n.goalflowz-task-item-content:hover .goalflowz-task-label:not(.done) {\n    color: var(--text-accent);\n}\n\n.goalflowz-task-delete {\n    opacity: 0;\n    color: var(--text-muted);\n    padding: 4px;\n    border-radius: 4px;\n    cursor: pointer;\n    transition: all 0.2s ease;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n\n.goalflowz-task-item-content:hover .goalflowz-task-delete {\n    opacity: 1;\n}\n\n.goalflowz-task-delete:hover {\n    color: var(--text-error);\n    background-color: var(--background-modifier-error);\n    transform: scale(1.1);\n}\n\n.goalflowz-task-actions {\n    display: flex;\n    gap: 4px;\n    align-items: center;\n}\n\n.goalflowz-task-action-button {\n    opacity: 0;\n    padding: 4px;\n    border-radius: 4px;\n    border: none;\n    cursor: pointer;\n    font-size: 14px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: all 0.2s ease;\n    background: var(--background-modifier-border);\n    color: var(--text-normal);\n}\n\n.goalflowz-task-item-content:hover .goalflowz-task-action-button {\n    opacity: 1;\n}\n\n.goalflowz-task-action-button:hover {\n    transform: scale(1.1);\n}\n\n.goalflowz-task-action-button.optimizer:hover {\n    background: var(--interactive-accent);\n    color: var(--text-on-accent);\n}\n\n.goalflowz-task-action-button.generator:hover {\n    background: var(--text-accent);\n    color: var(--text-on-accent);\n}\n\n.goalflowz-planning-view {\n    display: flex;\n    flex-direction: column;\n    height: 100%;\n    overflow: hidden;\n}\n\n.goalflowz-planning-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 1rem;\n    background: var(--background-secondary);\n    border-bottom: 1px solid var(--background-modifier-border);\n}\n\n.goalflowz-planning-header h2 {\n    margin: 0;\n    font-size: 1.5em;\n    color: var(--text-normal);\n}\n\n.goalflowz-planning-controls {\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n}\n\n.goalflowz-planning-controls button {\n    padding: 0.25rem 0.5rem;\n    border: 1px solid var(--background-modifier-border);\n    border-radius: 4px;\n    background: var(--background-primary);\n    color: var(--text-normal);\n    cursor: pointer;\n}\n\n.goalflowz-planning-controls button:hover {\n    background: var(--background-primary-alt);\n}\n\n.goalflowz-planning-controls span {\n    padding: 0.25rem 0.5rem;\n    color: var(--text-muted);\n}\n\n.goalflowz-planning-content {\n    flex: 1;\n    overflow-y: auto;\n}\n\n.goalflowz-planning-filters {\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n    padding: 16px;\n    background: var(--background-secondary);\n    border-radius: 8px;\n}\n\n.goalflowz-search-row input {\n    width: 100%;\n    padding: 8px;\n    border-radius: 4px;\n    border: 1px solid var(--background-modifier-border);\n}\n\n.goalflowz-filters-row {\n    display: flex;\n    gap: 16px;\n    flex-wrap: wrap;\n}\n\n.goalflowz-filter-group {\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n}\n\n.goalflowz-filter-group label {\n    font-size: 0.8em;\n    color: var(--text-muted);\n}\n\n.goalflowz-filter-group select {\n    padding: 4px 8px;\n    border-radius: 4px;\n    border: 1px solid var(--background-modifier-border);\n}\n\n.goalflowz-sort-controls {\n    display: flex;\n    gap: 4px;\n    align-items: center;\n}\n\n.goalflowz-sort-direction {\n    padding: 4px 8px;\n    border-radius: 4px;\n    border: 1px solid var(--background-modifier-border);\n    background: var(--background-primary);\n    cursor: pointer;\n}\n\n.goalflowz-notes-list {\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n}\n\n.goalflowz-no-content {\n    text-align: center;\n    padding: 32px;\n    color: var(--text-muted);\n}\n\n.goalflowz-note-item {\n    padding: 16px;\n    background: var(--background-primary);\n    border: 1px solid var(--background-modifier-border);\n    border-radius: 8px;\n    transition: all 0.2s ease;\n    cursor: pointer;\n}\n\n.goalflowz-note-item:hover {\n    transform: translateX(4px);\n    border-color: var(--text-accent);\n}\n\n.goalflowz-note-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 8px;\n}\n\n.goalflowz-note-title {\n    margin: 0;\n    font-size: 1.2em;\n}\n\n.goalflowz-header-right {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n}\n\n.goalflowz-note-meta {\n    display: flex;\n    gap: 16px;\n    font-size: 0.8em;\n    color: var(--text-muted);\n    margin-bottom: 8px;\n}\n\n.goalflowz-article-status {\n    padding: 4px 8px;\n    border-radius: 4px;\n    border: none;\n    font-size: 0.9em;\n    cursor: pointer;\n}\n\n.goalflowz-status-todo {\n    background: var(--background-modifier-error);\n    color: var(--text-error);\n}\n\n.goalflowz-status-todo option {\n    background: var(--background-primary);\n    color: white;\n}\n\n.goalflowz-status-in-progress {\n    background: var(--background-modifier-warning);\n    color: var(--text-warning);\n}\n\n.goalflowz-status-in-progress option {\n    background: var(--background-primary);\n    color: white;\n}\n\n.goalflowz-status-done {\n    background: var(--background-modifier-success);\n    color: var(--text-success);\n}\n\n.goalflowz-status-done option {\n    background: var(--background-primary);\n    color: white;\n}\n\n.view-toggle {\n    margin-left: 1rem;\n    padding: 0.25rem 0.5rem;\n    border-radius: 4px;\n    background: var(--interactive-accent);\n    color: var(--text-on-accent);\n    border: none;\n    cursor: pointer;\n}\n\n.view-toggle:hover {\n    background: var(--interactive-accent-hover);\n}";
const listViewStyles = ".goalflowz-notes-list {\n   display: flex;\n   flex-direction: column;\n   gap: 8px;\n}\n\n.goalflowz-no-content {\n   text-align: center;\n   padding: 32px;\n   color: var(--text-muted);\n}\n\n.goalflowz-note-item {\n   padding: 16px;\n   background: var(--background-primary);\n   border: 1px solid var(--background-modifier-border);\n   border-radius: 8px;\n   transition: all 0.2s ease;\n   cursor: pointer;\n}\n\n.goalflowz-note-item:hover {\n   transform: translateX(4px);\n   border-color: var(--text-accent);\n}";
const weekViewStyles = "/* Styles pour la grille des notes */\n.goalflowz-notes-grid {\n   display: grid;\n   grid-template-columns: repeat(3, 1fr);\n   gap: 16px;\n   padding: 16px;\n}\n\n/* Styles pour la vue kanban */\n.goalflowz-notes-week {\n   display: flex;\n   flex-direction: column;\n   gap: 1rem;\n   padding: 1rem;\n   width: 100%;\n   height: 100%;\n   overflow: auto;\n}\n\n.week-header {\n   display: grid;\n   grid-template-columns: repeat(7, 1fr);\n   gap: 0.5rem;\n   position: sticky;\n   top: 0;\n   background: var(--background-primary);\n   z-index: 1;\n   padding: 0.5rem;\n}\n\n.day-header {\n   padding: 0.5rem;\n   text-align: center;\n   font-weight: bold;\n   background: var(--background-secondary);\n   border-radius: 4px;\n}\n\n.week-content {\n   display: grid;\n   grid-template-columns: repeat(7, 1fr);\n   gap: 0.5rem;\n   min-height: 200px;\n   padding: 0.5rem;\n}\n\n.day-content {\n   padding: 0.5rem;\n   background: var(--background-primary-alt);\n   border-radius: 4px;\n   min-height: 100%;\n   display: flex;\n   flex-direction: column;\n   gap: 0.5rem;\n}\n\n/* Styles pour les notes dans la vue kanban */\n.goalflowz-week-note-item {\n   background: var(--background-primary);\n   border: 1px solid var(--background-modifier-border);\n   border-radius: 4px;\n   padding: 0.75rem;\n   cursor: pointer;\n   transition: all 0.2s ease;\n}\n\n.goalflowz-week-note-item:hover {\n   transform: scale(1.02);\n   border-color: var(--text-accent);\n   background: var(--background-modifier-hover);\n}\n\n.goalflowz-week-note-header {\n   display: flex;\n   justify-content: space-between;\n   align-items: flex-start;\n}\n\n/* Styles pour les notes étendues */\n.note-title {\n    font-weight: bold;\n    margin-bottom: 0.25rem;\n}\n\n.note-details {\n    font-size: 0.9em;\n    color: var(--text-muted);\n}\n\n.note-tasks {\n    margin-top: 0.5rem;\n}\n\n.task-item {\n    display: flex;\n    gap: 0.5rem;\n    align-items: center;\n    padding: 0.25rem 0;\n}\n\n/* Styles pour la vue compacte */\n.goalflowz-notes-week.compact-view .week-header,\n.goalflowz-notes-week.compact-view .week-content {\n    grid-template-columns: repeat(3, 1fr);\n}\n\n.weekend-label {\n    display: block;\n    font-size: 0.9em;\n    opacity: 0.8;\n}\n\n/* Styles pour le jour actuel */\n.day-header.is-today {\n    background: var(--interactive-accent);\n    color: var(--text-on-accent);\n}\n\n.day-content.is-today {\n    border: 2px solid var(--interactive-accent);\n}\n\n/* Autres styles utilitaires */\n.no-notes {\n    text-align: center;\n    color: var(--text-muted);\n    padding: 1rem;\n    font-style: italic;\n}\n\n.loading {\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    height: 200px;\n    color: var(--text-muted);\n    font-style: italic;\n}\n\n/* Style pour le conteneur des notes dans un jour */\n.day-notes {\n    display: flex;\n    flex-direction: column;\n    gap: 0.5rem;\n}";
